// HasRepoConfig applies the HasEdge predicate on the "repo_config" edge.
func HasRepoConfig() predicate.PRSyncJob {
	return predicate.PRSyncJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RepoConfigTable, RepoConfigColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRepoConfigWith applies the HasEdge predicate on the "repo_config" edge with a given conditions (other predicates).
func HasRepoConfigWith(preds ...predicate.RepoConfig) predicate.PRSyncJob {
	return predicate.PRSyncJob(func(s *sql.Selector) {
		step := newRepoConfigStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PRSyncJob) predicate.PRSyncJob {
	return predicate.PRSyncJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PRSyncJob) predicate.PRSyncJob {
	return predicate.PRSyncJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PRSyncJob) predicate.PRSyncJob {
	return predicate.PRSyncJob(sql.NotPredicates(p))
}
